def __init__(self, verbose=None, name="Unknown"):
    try:
        super(AtExitEvent, self).__init__(verbose)
    except TypeError:
        # in Python 3 there is no verbose argument
        super(AtExitEvent, self).__init__()
    self.__name = name
    self.__atexit = False

